#!/usr/bin/env node
/* eslint-disable no-console */

/**
 * Ensures documentation portal placeholders exist under /public/docs.
 * This prevents 404s for documentation endpoints during development and deployment.
 *
 * The real reports are generated by:
 * - Tests:        `yarn test:all`
 * - A11y audit:   `yarn dev` then `yarn audit:a11y`
 * - API docs:     `yarn docs:jsdoc`
 */

const fs = require("fs");
const path = require("path");

const projectRoot = path.resolve(__dirname, "..");

const PATHS = {
  docsRoot: path.join(projectRoot, "public", "docs"),
  docsIndex: path.join(projectRoot, "public", "docs", "index.html"),
  testsDir: path.join(projectRoot, "public", "docs", "tests"),
  testsIndex: path.join(projectRoot, "public", "docs", "tests", "index.html"),
  a11yDir: path.join(projectRoot, "public", "docs", "accessibility"),
  a11yIndex: path.join(
    projectRoot,
    "public",
    "docs",
    "accessibility",
    "index.html",
  ),
  jsdocDir: path.join(projectRoot, "public", "docs", "jsdoc"),
  jsdocIndex: path.join(projectRoot, "public", "docs", "jsdoc", "index.html"),
};

function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function writeIfMissing(filePath, content) {
  if (!fs.existsSync(filePath)) fs.writeFileSync(filePath, content, "utf8");
}

function main() {
  ensureDir(PATHS.docsRoot);
  ensureDir(PATHS.testsDir);
  ensureDir(PATHS.a11yDir);
  ensureDir(PATHS.jsdocDir);

  // These are committed into the repo, but we also ensure them here so a fresh
  // checkout (or CI) never serves a 404 if they were removed accidentally.
  writeIfMissing(
    PATHS.docsIndex,
    `<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>Documentation Portal</title></head><body><p>Missing portal file. Please restore <code>public/docs/index.html</code>.</p></body></html>\n`,
  );
  writeIfMissing(
    PATHS.testsIndex,
    `<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>Test Results</title></head><body><p>Placeholder. Run <code>yarn test</code> to generate the test report.</p><p><a href="/docs/index.html">Back</a></p></body></html>\n`,
  );
  writeIfMissing(
    PATHS.a11yIndex,
    `<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>Accessibility Audit</title></head><body><p>Placeholder. Start the dev server and run <code>yarn audit:a11y</code>.</p><p><a href="/docs/index.html">Back</a></p></body></html>\n`,
  );
  writeIfMissing(
    PATHS.jsdocIndex,
    `<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>API Docs</title></head><body><p>Placeholder. Run <code>yarn docs:jsdoc</code>.</p><p><a href="/docs/index.html">Back</a></p></body></html>\n`,
  );

  console.log("✅ Documentation placeholders ensured under /public/docs");
}

main();


